CREATE TABLE IF NOT EXISTS kr_users (id CHAR(36) PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,is_admin TINYINT NOT NULL DEFAULT 0,auth_version INT NOT NULL DEFAULT 1,created DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kr_bootstrap (id INT PRIMARY KEY,complete TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
INSERT IGNORE INTO kr_bootstrap(id,complete) VALUES(1,0);
CREATE TABLE IF NOT EXISTS kr_businesses (owner CHAR(36) PRIMARY KEY,data MEDIUMTEXT NOT NULL,version INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kr_customers (id CHAR(36) PRIMARY KEY,owner CHAR(36) NOT NULL,data TEXT NOT NULL,created DATETIME NOT NULL,INDEX(owner)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kr_counters (owner CHAR(36) PRIMARY KEY,value INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kr_documents (id CHAR(36) PRIMARY KEY,owner CHAR(36) NOT NULL,number VARCHAR(50) NOT NULL,kind VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,data MEDIUMTEXT NOT NULL,total BIGINT NOT NULL,paid BIGINT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 0,source_offer CHAR(36) NULL,created DATETIME NOT NULL,UNIQUE(owner,number),UNIQUE(owner,source_offer),INDEX(owner,created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kr_payments (id CHAR(36) PRIMARY KEY,owner CHAR(36) NOT NULL,document_id CHAR(36) NOT NULL,amount BIGINT NOT NULL,date DATE NOT NULL,INDEX(owner,date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kr_invites (token_hash CHAR(64) PRIMARY KEY,email VARCHAR(190) NOT NULL,expires DATETIME NOT NULL,used TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kr_rate_limits (bucket CHAR(64) PRIMARY KEY,attempts INT NOT NULL,expires BIGINT NOT NULL,INDEX(expires)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS kr_user_access (user_id CHAR(36) PRIMARY KEY,state VARCHAR(16) NOT NULL DEFAULT 'active',activated TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS kr_dunning_fees (document_id CHAR(36) PRIMARY KEY,owner CHAR(36) NOT NULL,amount BIGINT NOT NULL,created DATETIME NOT NULL,INDEX(owner)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
